//! WebP tests: VP8L lossless (byte-exact) and VP8 lossy (PIL/libwebp tolerance).
//!
//! The simple-code VP8L fixtures are generated by `tests/fixtures/generate_webp.py` and
//! validated with PIL/libwebp; their expected ARGB->RGBA output is stored as `.rgba` raw
//! bytes so the Rust decoder is checked byte-for-byte against an independent decoder.
//!
//! The VP8 lossy fixtures (`photo_lossy_q75/q90`, `photo_1024x768_lossy`) are real
//! PIL/libwebp encodings; their `.rgba` files are PIL decodes (independent oracle) and the
//! lossy tests compare within a tolerance instead of byte-for-byte (the in-tree decoder is
//! a from-scratch VP8 port, not libwebp: chroma upsampling/loop-filter rounding can differ
//! by a few units).

use std::path::Path;

use megi_image::{ImageError, ImageFormat, decode, detect_format};

fn fixture(relative: &str) -> Vec<u8> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/webp")
        .join(relative);
    std::fs::read(&path).unwrap_or_else(|error| panic!("fixture {}: {error}", path.display()))
}

mod animated;
mod container;
mod lossless;
mod lossy;

/// Extracts a chunk payload from a RIFF/WEBP container by FourCC.
fn find_chunk_payload<'a>(bytes: &'a [u8], id: &[u8; 4]) -> Option<&'a [u8]> {
    let mut offset = 12usize;
    while offset + 8 <= bytes.len() {
        let length = u32::from_le_bytes([
            bytes[offset + 4],
            bytes[offset + 5],
            bytes[offset + 6],
            bytes[offset + 7],
        ]) as usize;
        let start = offset + 8;
        if &bytes[offset..offset + 4] == id {
            return bytes.get(start..start + length);
        }
        offset = start + length + (length & 1);
    }
    None
}

/// Extracts the `VP8 ` chunk payload from a RIFF/WEBP container.
fn vp8_payload(bytes: &[u8]) -> &[u8] {
    let mut offset = 12usize;
    while offset + 8 <= bytes.len() {
        let length = u32::from_le_bytes([
            bytes[offset + 4],
            bytes[offset + 5],
            bytes[offset + 6],
            bytes[offset + 7],
        ]) as usize;
        let start = offset + 8;
        if &bytes[offset..offset + 4] == b"VP8 " {
            return &bytes[start..start + length];
        }
        offset = start + length + (length & 1);
    }
    panic!("fixture has no VP8 chunk");
}

/// Builds a RIFF/WEBP container around `(chunk id, payload)` pairs.
fn riff_container(chunks: &[(&[u8; 4], &[u8])]) -> Vec<u8> {
    let mut body = Vec::from(*b"WEBP");
    for (id, payload) in chunks {
        body.extend_from_slice(*id);
        body.extend_from_slice(&(payload.len() as u32).to_le_bytes());
        body.extend_from_slice(payload);
        if payload.len() % 2 == 1 {
            body.push(0);
        }
    }
    let mut bytes = Vec::from(*b"RIFF");
    bytes.extend_from_slice(&(body.len() as u32).to_le_bytes());
    bytes.extend_from_slice(&body);
    bytes
}

/// Compares two RGBA8 buffers (alpha ignored) and returns (max, mean) absolute error
/// over the RGB channels.
fn compare_rgba(decoded: &[u8], oracle: &[u8]) -> (i32, f64) {
    assert_eq!(decoded.len(), oracle.len());
    let mut max = 0i32;
    let mut sum = 0i64;
    for (ours, theirs) in decoded
        .as_chunks::<4>()
        .0
        .iter()
        .zip(oracle.as_chunks::<4>().0.iter())
    {
        for channel in 0..3 {
            let delta = (i32::from(ours[channel]) - i32::from(theirs[channel])).abs();
            max = max.max(delta);
            sum += i64::from(delta);
        }
    }
    let count = (decoded.len() / 4 * 3) as f64;
    (max, sum as f64 / count)
}

fn push_riff_chunk(out: &mut Vec<u8>, id: &[u8; 4], payload: &[u8]) {
    out.extend_from_slice(id);
    out.extend_from_slice(&(payload.len() as u32).to_le_bytes());
    out.extend_from_slice(payload);
    if payload.len() % 2 == 1 {
        out.push(0);
    }
}

fn extract_vp8l_chunk(webp: &[u8]) -> Vec<u8> {
    let mut off = 12;
    while off + 8 <= webp.len() {
        let id = &webp[off..off + 4];
        let len = u32::from_le_bytes(webp[off + 4..off + 8].try_into().unwrap()) as usize;
        if id == b"VP8L" {
            return webp[off + 8..off + 8 + len].to_vec();
        }
        off += 8 + len + (len & 1);
    }
    panic!("missing VP8L chunk in fixture");
}

fn encode_u24_le(v: u32) -> [u8; 3] {
    [
        (v & 0xff) as u8,
        ((v >> 8) & 0xff) as u8,
        ((v >> 16) & 0xff) as u8,
    ]
}

type AnmfFrameSpec<'a> = (u32, u32, u32, u32, u32, u8, &'a [u8]);

fn build_animated_webp(
    canvas_w: u32,
    canvas_h: u32,
    bg_bgra: [u8; 4],
    loop_count: u16,
    frames: &[AnmfFrameSpec<'_>],
) -> Vec<u8> {
    let mut body = Vec::from(*b"WEBP");
    let mut vp8x = [0u8; 10];
    vp8x[0] = 0x12; // alpha + animation
    vp8x[4..7].copy_from_slice(&encode_u24_le(canvas_w - 1));
    vp8x[7..10].copy_from_slice(&encode_u24_le(canvas_h - 1));
    push_riff_chunk(&mut body, b"VP8X", &vp8x);

    let mut anim = [0u8; 6];
    anim[0..4].copy_from_slice(&bg_bgra);
    anim[4..6].copy_from_slice(&loop_count.to_le_bytes());
    push_riff_chunk(&mut body, b"ANIM", &anim);

    for &(fx, fy, fw, fh, delay_ms, flags, vp8l) in frames {
        let mut anmf = Vec::new();
        anmf.extend_from_slice(&encode_u24_le(fx / 2));
        anmf.extend_from_slice(&encode_u24_le(fy / 2));
        anmf.extend_from_slice(&encode_u24_le(fw - 1));
        anmf.extend_from_slice(&encode_u24_le(fh - 1));
        anmf.extend_from_slice(&encode_u24_le(delay_ms));
        anmf.push(flags);
        push_riff_chunk(&mut anmf, b"VP8L", vp8l);
        push_riff_chunk(&mut body, b"ANMF", &anmf);
    }

    let mut out = Vec::from(*b"RIFF");
    out.extend_from_slice(&(body.len() as u32).to_le_bytes());
    out.extend_from_slice(&body);
    out
}
